ALTER TABLE public.visit_participants DROP CONSTRAINT visit_participants_visit_id_staff_id_key;
CREATE UNIQUE INDEX one_active_visit_participant ON public.visit_participants(visit_id,staff_id) WHERE active;
DROP POLICY "participants read" ON public.visit_participants;CREATE POLICY "participants read" ON public.visit_participants FOR SELECT TO authenticated USING(staff_id IN(SELECT public.my_staff_ids()) OR public.can_access_field_visit(visit_id));
DROP POLICY "msgs read" ON public.staff_messages;
CREATE POLICY "msgs read" ON public.staff_messages FOR SELECT TO authenticated USING(public.is_staff(auth.uid()) AND (to_staff IS NULL OR from_user=auth.uid() OR to_staff IN(SELECT public.my_staff_ids()) OR public.is_ops(auth.uid())) AND (visit_id IS NULL OR public.can_access_field_visit(visit_id)) AND (task_id IS NULL OR NOT public.is_aux_only(auth.uid()) OR EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=task_id AND t.staff_id IN(SELECT public.my_staff_ids()))));
CREATE OR REPLACE FUNCTION public.can_read_field_file(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(auth.uid()) AND EXISTS(SELECT 1 FROM public.field_files f WHERE f.path=_path AND (f.user_id=auth.uid() OR public.is_ops(auth.uid()) OR (f.visit_id IS NOT NULL AND public.can_access_field_visit(f.visit_id)) OR (f.task_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=f.task_id AND (NOT public.is_aux_only(auth.uid()) OR t.staff_id IN(SELECT public.my_staff_ids())))) OR (f.visit_id IS NULL AND f.task_id IS NULL AND (f.to_staff IN(SELECT public.my_staff_ids()) OR EXISTS(SELECT 1 FROM public.staff_messages m WHERE m.attachment_path=f.path AND m.to_staff IS NULL))))) $$;
CREATE OR REPLACE FUNCTION public.field_supplies_ready(_visit text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_access_field_visit(_visit) AND NOT EXISTS(SELECT 1 FROM public.visit_supply_requirements r WHERE r.visit_id=_visit AND r.qty>coalesce((SELECT sum(s.qty) FROM public.inventory_reservations s WHERE s.visit_id=_visit AND s.item_id=r.item_id AND s.status IN('reservado','consumido')),0)) $$;
CREATE OR REPLACE FUNCTION public.field_day_pending(_staff text,_day date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb;BEGIN IF NOT public.is_ops(auth.uid()) AND _staff NOT IN(SELECT public.my_staff_ids()) THEN RAISE EXCEPTION 'Sin acceso a esta jornada';END IF;SELECT coalesce(jsonb_agg(x),'[]') INTO result FROM (
 SELECT v.id,'visita'::text kind,v.service title,true critical FROM public.visits v WHERE (v.operational_on=_day OR v.operational_on IS NULL) AND v.status NOT IN('finalizada','cancelada') AND ((v.staff_id=_staff AND NOT EXISTS(SELECT 1 FROM public.visit_executions e WHERE e.visit_id=v.id AND e.state IN('SERVICE_FINISHED','ADMINISTRATIVE_REVIEW','ADMINISTRATIVELY_COMPLETED','NOT_PERFORMED'))) OR EXISTS(SELECT 1 FROM public.visit_participants p WHERE p.visit_id=v.id AND p.staff_id=_staff AND p.active AND p.support_state<>'COMPLETED'))
 UNION ALL SELECT t.id,'tarea',t.title,t.critical FROM public.tasks t WHERE t.staff_id=_staff AND NOT t.done AND coalesce(t.stage,'assigned')<>'cancelled' AND (t.due_at IS NULL OR(t.due_at AT TIME ZONE 'America/Bogota')::date<=_day)
 UNION ALL SELECT k.id::text,'kit','Kit pendiente de devolver',true FROM public.kit_assignments k WHERE k.staff_id=_staff AND k.state<>'returned' AND (k.created_at AT TIME ZONE 'America/Bogota')::date<=_day
 UNION ALL SELECT i.id,'incidencia',i.title,i.severity='alta' FROM public.incidents i WHERE i.status<>'cerrada' AND (i.assignee_staff=_staff OR (i.assignee_staff IS NULL AND i.owner=(SELECT name FROM public.staff_members WHERE id=_staff)))
 ) x;RETURN result;END $$;
CREATE FUNCTION public.guard_task_transfer_integrity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.staff_id IS DISTINCT FROM OLD.staff_id AND NOT public.is_ops(auth.uid()) THEN IF (to_jsonb(NEW)-ARRAY['staff_id','stage','version','history']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['staff_id','stage','version','history']) OR NEW.stage IS DISTINCT FROM coalesce(OLD.stage,'assigned') THEN RAISE EXCEPTION 'La entrega no cambia los datos ni el estado de la tarea';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER aab_task_transfer_integrity BEFORE UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.guard_task_transfer_integrity();
CREATE FUNCTION public.escalate_blocked_field_task() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.stage='blocked' AND OLD.stage IS DISTINCT FROM NEW.stage THEN INSERT INTO public.staff_messages(from_user,from_name,to_staff,body,urgent) VALUES(auth.uid(),(SELECT name FROM public.staff_members WHERE id=NEW.staff_id),NULL,'Tarea bloqueada: '||NEW.title||'. Motivo: '||NEW.reason,true);END IF;RETURN NEW;END $$;
CREATE TRIGGER blocked_task_escalation AFTER UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.escalate_blocked_field_task();
REVOKE ALL ON FUNCTION public.guard_task_transfer_integrity(),public.escalate_blocked_field_task() FROM PUBLIC,anon;